#!/usr/bin/env ruby
# Regenerates assets/css/highlight.css from Rouge's own themes, so code
# highlighting needs no CSS framework and no runtime JS.
#   rake highlight   (or: ruby scripts/gen-highlight.rb)
require "rouge"

LIGHT = "github"      # applied by default
DARK  = "github.dark" # applied under [data-theme=dark]

light = Rouge::Theme.find(LIGHT).new(scope: ".highlight").render
dark  = Rouge::Theme.find(DARK).new(scope: "[data-theme=dark] .highlight").render

out = <<~CSS
  /* Generated by scripts/gen-highlight.rb (Rouge #{Rouge.version}). Do not edit.
     Light: #{LIGHT} · Dark: #{DARK} */
  #{light}

  #{dark}
CSS

path = File.expand_path("../assets/css/highlight.css", __dir__)
File.write(path, out)
puts "wrote #{path} (#{out.bytesize} bytes)"
